mapper.jsonStringBodyContent:
{
  "system_instruction": {
    "parts": [
      {
        "text": "You are a customer support triage agent. Classify the inquiry, assess sentiment, determine churn risk, and route to either TIER_1 or TIER_2. Output strict JSON matching the requested schema."
      }
    ]
  },
  "contents": [
    {
      "parts": [
        {
          "text": "Sender: {{2.sender_email}}\nSubject: {{2.subject}}\nMessage:{{2.body}} "
        }
      ]
    }
  ],
  "generationConfig": {
    "response_mime_type": "application/json",
    "response_schema": {
      "type": "OBJECT",
      "properties": {
        "route": {
          "type": "STRING",
          "enum": [
            "TIER_1",
            "TIER_2"
          ]
        },
        "intent": {
          "type": "STRING"
        },
        "urgency": {
          "type": "INTEGER"
        },
        "sentiment": {
          "type": "STRING",
          "enum": [
            "positive",
            "neutral",
            "negative"
          ]
        },
        "summary": {
          "type": "STRING"
        }
      },
      "required": [
        "route",
        "intent",
        "urgency",
        "sentiment",
        "summary"
      ]
    }
  }
}

{
  "system_instruction": {
    "parts": [
      {
        "text": "You are a professional customer support specialist. Answer the customer's question clearly, warmly, and concisely using ONLY the provided FAQ context. Do not invent steps. If the information is missing from the FAQ, advise them that a team member will follow up shortly."
      }
    ]
  },
  "contents": [
    {
      "parts": [
        {
          "text": "Sender: {{escapeJSON(2.sender_email)}}\nSubject: {{escapeJSON(2.subject)}}\nMessage: {{escapeJSON(2.body)}}"
        }
      ]
    }
  ],
  "generationConfig": {
    "temperature": 0.2
  }
}

